"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9547],{75032:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PlacementCameraController","desc":"Takes exclusive ownership of the camera while build mode is active: a\\nfixed-height, fixed-pitch, yaw-locked-at-entry top-down view that follows\\nthe player. Restores Enum.CameraType.Custom on exit. Independent of\\nCameraController (Enum.CameraType.Custom + CameraOffset spring), which is\\nharmlessly inert while this module owns the camera \u2014 it never touches\\nCamera.CFrame or Camera.CameraType.\\n\\nBecause this camera is Scriptable and driven entirely by hrp.Position plus\\na fixed yaw/pitch/height, it does not rotate in response to mouse delta\\nthe way the normal locked third-person camera does. The placement raycast\\naims from the mouse cursor\'s actual on-screen position, so on PC this\\nmodule also frees the cursor (via Signals.RequestMouseIcon) while build\\nmode is active so the player can aim.","realm":["Client"],"source":{"line":22,"path":"src/StarterPlayer/StarterPlayerScripts/PlacementCameraController.client.luau"}}')}}]);